// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, address target, uint256 amount) public {
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != address(c));
        vm.assume(nonOwner != target);
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        vm.deal(nonOwner, 0);
        vm.prank(nonOwner);
        try c.sendMoney(target, amount) {
            assertTrue(target.balance == 0);
        } catch {
            assertTrue(true);
        }
    }
}
